-- Actual product cost excludes lapse/unabsorbed salary and general management overhead.
create or replace function public.rr_upm_product_cost_actual_v679(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare c jsonb:=public.rr_upm_final_costing_private_v400(p_canonical_lot_id,p_data_mode);lapse numeric:=coalesce((c->>'lapse_staff_per_pc')::numeric,0);oh numeric:=coalesce((c->>'overhead_per_pc')::numeric,0);oldbase numeric:=coalesce((c->>'base_cost_per_pc')::numeric,0);actualbase numeric;margin numeric:=coalesce((c->>'owner_margin_per_pc')::numeric,0);appbase numeric;finalrate numeric;begin actualbase:=greatest(oldbase-lapse-oh,0);appbase:=public.rr_cost_component_round_v675(actualbase);finalrate:=public.rr_cost_final_rate_round_v675(appbase+margin);return c||jsonb_build_object('version','V679_ACTUAL_PRODUCT_COST','legacy_base_cost_per_pc',oldbase,'excluded_lapse_staff_per_pc',lapse,'excluded_general_overhead_per_pc',oh,'actual_product_cost_raw_per_pc',round(actualbase,4),'actual_product_cost_applicable_per_pc',appbase,'base_cost_per_pc',appbase,'final_sale_rate',finalrate,'lapse_product_cost_impact',0,'general_overhead_product_cost_impact',0,'management_visibility_function','rr_costing_management_live_v677','rule','PRODUCT COST EXCLUDES LAPSE/UNABSORBED SALARY AND GENERAL MANAGEMENT OVERHEAD; OWNER MARGIN REMAINS COMMERCIAL BUFFER');end $function$;